        "荷兰有 12 个省（`provincies`），每个省有省会。西部四大城市组成“兰斯塔德”（`Randstad`）：Amsterdam、Rotterdam、Den Haag、Utrecht。这里工作、交通、学校、医院多，但也更拥挤，容易堵车（`file`）。",
        "荷兰很多水域和河流很重要：`de Rijn`、`de Maas`、`IJsselmeer`、`Waddenzee`。`polder` 是以前是水、后来排水造出来的土地，Flevoland 是典型例子。天气常常变化，叫 `wisselvallig weer`。四季是 `lente`、`zomer`、`herfst`、`winter`。",
        "荷兰是民主国家（`democratie`），没有总统，有国王（`koning`）。政府和议会在 Den Haag。荷兰也属于欧盟（`Europese Unie`），使用欧元（`euro`）。PDF 中的人口、外国出生人口等数字属于可能需要核对最新信息。"
