        "家庭医生会听症状、提问、检查，可能建议等待、开药（`recept`）、治疗，或用转诊信（`verwijsbrief`）把你转到专科医生（`specialist`）。一般不能自己直接去专科。紧急生命危险打 112；晚上、周末先打自己的 huisarts 或 huisartsenpost；真正急诊可去 SEH（`Spoedeisende Hulp`）。",
