      "summary": "荷兰住房分为买房（`een huis kopen`）和租房（`een huis huren`）。买房通常需要向银行贷款，叫 `hypotheek`，收入和固定工作会影响可贷金额。买房时可能通过房产中介（`makelaar`）看房、谈价，最后去公证人（`notaris`）签合同。",
