        "租房包括社会住房（`sociale huurwoning`）和自由市场住房（`vrije sector`）。社会住房租金较低，但可能等待很久，通常要注册、按等待时间排序；紧急情况可向 gemeente 申请 `urgentieverklaring`，但不容易拿到。自由市场租金高，可以通过亲友、广告、中介寻找。",
