        "`parttime` 是兼职，`fulltime` 是全职。工作时间可能 `regelmatig` 或 `onregelmatig`。雇主是 `werkgever`，雇员是 `werknemer`。",
        "找工作叫 `solliciteren`。你要看职位（`functie`）、任务（`taken`）、职位要求（`functie-eisen`）、工作时间、薪资、截止日期等。申请通常包括 CV、求职信（`sollicitatiebrief`）、面试（`sollicitatiegesprek`）。面试要准时、穿整洁衣服、握手、眼神交流、提前准备。",
        "失业者可到 UWV 登记。`WW-uitkering` 给符合条件的失业者，通常有求职义务；`WIA-uitkering` 给因健康原因不能工作者；`bijstand` 是没有其他收入或福利时的最低生活救助。具体条件会变化，要核对最新信息。",
        "工作合同写 `arbeidsvoorwaarden`：工时、工资、试用期、假期、开始日期等。`cao` 是行业集体劳动协议。工资单上 `bruto salaris` 是税前，`netto salaris` 是到手。每年有 `jaaropgave` 用于报税。`vakbond` 帮助员工，`OR` 是企业员工代表组织。`Arbowet` 保护工作健康安全。"
